  const { limiter, loginGuard, requestLogger } = require("./middleware/rateLimit");
  const mkRes = () => { const h = {}; return { headers: h, statusCode: 200, on(ev, fn) { (this.fns = this.fns || {})[ev] = fn; }, set(k, v) { h[k] = v; }, status(c) { this.statusCode = c; return this; }, json(b) { this.body = b; return this; } }; };
  const lim = limiter({ windowMs: 60000, max: 3 }); const req = { headers: { "x-forwarded-for": "9.9.9.9, 1.1.1.1" }, ip: "::1" }; const results = []; for (let i = 0; i < 5; i++) { const res = mkRes(); let passedThrough = false; lim(req, res, () => (passedThrough = true)); results.push(passedThrough ? 200 : res.statusCode); }
  assert.deepEqual(results, [200, 200, 200, 429, 429]); const other = mkRes(); let otherPassed = false; lim({ headers: { "x-forwarded-for": "8.8.8.8" }, ip: "::1" }, other, () => (otherPassed = true)); assert.ok(otherPassed); ok("the rate limiter lets 3 requests through, blocks the 4th and 5th (429), and counts each address separately");
