  for (let i = 0; i < 5; i++) { const res = mkRes(); let next = false; guard.check(lreq, res, () => (next = true)); if (next) { res.statusCode = 401; res.fns.finish(); outcomes.push("tried"); } else outcomes.push(res.statusCode); }
