  const guard2 = loginGuard({ max: 2 }); const g2 = { headers: {}, body: { email: "ok@b.lk" }, ip: "5.5.5.5" }; for (const status of [401, 200, 401, 200, 401]) { const res = mkRes(); let n = false; guard2.check(g2, res, () => (n = true)); assert.ok(n, "should not be blocked"); res.statusCode = status; res.fns.finish(); } ok("a correct login resets the count, so a real farmer who mistypes now and then is never locked out");
