  const dedupe = "push-dup-" + Date.now(); await notifyFarmer(F2.id, { type: "order_update", title: "x", message: "y", dedupeKey: dedupe }); await notifyFarmer(F2.id, { type: "order_update", title: "x", message: "y", dedupeKey: dedupe }); assert.equal(sent.length, 2); await http("DELETE", "/notifications/device", { token: F2.token, body: { token: "f".repeat(40) } }); assert.equal(await DeviceToken.countDocuments({ user: F2.id }), 0); ok("push: phones register a device token; every new notification is pushed once (duplicates are not); tokens can be removed; no phone = skipped");

